assert set(copy)=={p['family'] for p in plan['products']},set(p['family'] for p in plan['products'])-set(copy)
for p in plan['products']:
 n=p['catalogue_name'];title=p['retail_name'];family=p['family'];a,b=copy[family]
 # Finish names describe colour and appearance, without claiming a casting material.
 title=title.replace('Gold Leaf Finish','Gold Finish');p['retail_name']=title
 if family=='Acanthus':
  if 'Flower' in n:a='A single botanical form opens across this relief, with broad, flowing curves that give the flower its sculptural presence. The design keeps the details simple so that light and shadow can follow the contours.'
  elif 'Two Leaves' in n:a='Two stylised leaves rise together in a balanced botanical relief. Their long curves create a gentle tension between symmetry and growth, with light tracing the edges of the design.'
  elif 'One Leaf' in n:a='A single sweeping leaf gives this relief its graceful, upright movement. Its sculpted curve brings a botanical detail into focus, with shadows deepening around the raised form.'
 if family=='Ammonite':
  size='larger' if 'Large' in n else 'smaller';side='left' if 'Left' in n else 'right'
  b=f'This is the {side}-hand panel in the {size} Ammonite design. Display it as an individual sculptural fragment, or choose its matching partner to reveal the full spiral. Each panel is sold separately.'
 if family=='Deco Palm and Spiral' and 'Palm' in n:a='A stylised palm opens into a clean, decorative relief. The leaf-like lines create a confident botanical rhythm, with raised contours that catch the light.'
 if family=='Deco Palm and Spiral' and 'Spiral' in n:a='A flowing spiral brings an organic line into a clean, decorative relief. Its curling form catches light along the raised contours, giving the design a gentle sense of movement.'
 if family=='Fan Folds':
  if 'Cultivation' in n:a='Ordered folds suggest the rhythm of a cultivated landscape. Ridges and recesses give the relief an architectural character, while changing light keeps its surface in motion.'
  elif 'Swan' in n:a='Wing-like folds open into a graceful relief, recalling the sweep of a swan in movement. The design balances flowing curves with crisp edges that catch the light.'
  elif 'Fold Unfold' in n:a='A sequence of folded and opening forms creates a relief poised between structure and movement. Its edges and recesses invite light to trace the changes in direction.'
 if family=='Cup Ring and Spiral':
  if n.startswith('Cup Ring ('):a='A cup-and-ring motif turns an elemental circular mark into a tactile relief. Concentric contours catch the light, recalling the simple, absorbing patterns of ancient rock art.'
  elif n.startswith('Spiral White'):a='A curling spiral becomes a tactile relief, drawing the eye along a continuous, organic line. The design recalls the elemental marks found in ancient rock art without losing its contemporary clarity.'
 if family=='Riyadh Shell Spiral and Wave':
  if 'Dune Ripple' in n:a='Rippling contours bring the movement of a dune into the Riyadh collection. The raised lines create a rhythmic surface, with highlights and shadows following the pattern.'
  elif 'Plain Moon' in n:a='A simple moon-inspired form gives this Riyadh panel a calm, architectural presence. Its clear outline lets changing light define the relief without distracting detail.'
  else:a='A shell-like curve gives this Riyadh relief its flowing, organic movement. The form balances decorative detail with a clear architectural composition.'
 if family=='Seaweed Ripple' and 'Fossil' in n:a='A textured ripple suggests fossil-like traces and the marks left on a shore. The surface combines flowing movement with details that become clearer as light falls across the relief.'
 if family=='Spiralmoon' and 'Quarter Moon' in n:a='A quarter-moon form gives this relief a clear, sculptural outline. Its curve creates a quiet focal point, with light and shadow revealing the depth of the surface.'
 if family=='Wall Circle' and 'World Colours' in n:a='A circular form holds a varied palette of world-inspired colours with a warm brass-toned finish. The surface reads like an abstract map, inviting the eye to wander across its changing tones.'
 if family=='Wave and Moonshadow':
  a=('A moonshadow-inspired form creates a calm relief of curve and depth. Light moves across its contours, revealing a quiet balance of highlight and shade.' if ' 1 -' in n else 'A flowing wave gives this relief its gentle sense of movement. The raised form catches the light, creating a soft rhythm of highlights and shadows.')
  b+=' This listing is for one component; the companion piece is available separately.'
 finish=title.rsplit(' - ',1)[1] if ' - ' in title else ''
 if finish=='Abstract Cave Relief':finish=''
 if finish:
  if finish=='White':finish_sentence='The white finish keeps the focus on the form and its changing shadows.'
  elif finish in {'Cream','Beige'}:finish_sentence=f'The {finish.lower()} finish brings a soft, warm tone to the design.'
  elif finish=='Verdigris':finish_sentence='A verdigris-effect finish adds sea-green colour and a weathered visual character.'
  elif finish in {'Gold','Gold Finish'}:finish_sentence='A gold-toned finish adds warmth and catches the changing light.'
  elif finish in {'Bronze','Pewter','Silver','Copper'}:finish_sentence=f'A {finish.lower()}-toned finish adds a different mood to the relief and its shadows.'
  elif finish=='Rust':finish_sentence='A rust-effect finish adds earthy warmth to the relief.'
  else:finish_sentence=f'This version is offered in the {finish.lower()} colourway.'
 else:finish_sentence=''
 if 'Water Feature' in n or 'water feature' in n or family=='Knightsbridge Fountain':
  b+=' This is the water-feature version; please contact us to discuss the installation and water-system requirements.'
 fs={f['key']:f['value'] for f in source[p['catalogue_id']]['fields']}
 story=' '.join(x for x in (a,b,finish_sentence) if x)
 fix='Keyhole fixings are usually used. Other options, including French cleats, are available; the fixing choice can be agreed for your sculpture and wall.'
 # Keep technical construction assumptions in the internal specifications only.
 dimensions=re.sub(r';\s*framework metal\s+[^;]+','',fs['Dimensions / depth'],flags=re.I)
 weight=re.sub(r',?\s+for (?:lightweight )?(?:cast(?:-composite)?|rigid-board) construction','',fs['Weight'],flags=re.I)
 specs=[('Dimensions',dimensions),('Weight',weight),('Use','Suitable for outdoor use and indoor display.'),('Fixings',fix),('Availability',fs['Availability']),('Production lead time',fs['Lead time'].replace('–','-').replace('—','-')),('Delivery','Delivery is quoted separately. Please contact us for UK and international delivery options.')]
 desc='\n\n'.join([a,b,finish_sentence,'\n'.join(k+': '+v for k,v in specs)]).replace('—','-')
 body='<p>'+html.escape(a)+'</p><p>'+html.escape(b)+'</p>'+(('<p>'+html.escape(finish_sentence)+'</p>') if finish_sentence else '')+'<ul>'+''.join('<li><strong>'+html.escape(k)+':</strong> '+html.escape(v)+'</li>' for k,v in specs)+'</ul>'
 assert not re.search(r'\b(?:GFRC|Jesmonite|plaster|concrete|Royal Mail|Tracked 48)\b',body,re.I),(title,body)
 p.update(website_story=story,website_description=desc,website_description_html=body,website_fixings=fix)
(OUT/'website-copy-plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2))
