for p in plan['products']:
 page+='<article id="'+p['catalogue_id']+'"><h2>'+html.escape(p['retail_name'])+'</h2><small>'+html.escape(p['catalogue_name'])+' | '+p['catalogue_id']+'</small>'+p['website_description_html']+'</article>'
page+='</html>';(OUT/'retail-copy-review.html').write_text(page)
print(json.dumps({'descriptions':len(plan['products']),'families':len(copy),'public_copy_material_and_carrier_check':'PASS'}))
